def _validate_delimiter(delimiter):
    if not isinstance(delimiter, str) or len(delimiter) != 1 or delimiter in '"\r\n':
        raise ValueError("Expected one delimiter character other than quote, CR or LF")


def parse_record(text, delimiter=","):
    """Split one delimited record into its fields."""
    _validate_delimiter(delimiter)
    fields = []
    pos = 0
    while True:
        if text.startswith('"', pos):
            pos += 1
            parts = []
            while True:
                end = text.find('"', pos)
                if end == -1:
                    raise ValueError("Unclosed quoted field")
                parts.append(text[pos:end])
                pos = end + 1
                if not text.startswith('"', pos):
                    break
                parts.append('"')
                pos += 1
            field = ''.join(parts)
            if pos < len(text) and text[pos] != delimiter:
                raise ValueError("Expected delimiter after closing quote")
        else:
            end = text.find(delimiter, pos)
            if end == -1:
                end = len(text)
            field = text[pos:end]
            if any(char in field for char in '"\r\n'):
                raise ValueError("Unexpected quote or line break in unquoted field")
            pos = end
        fields.append(field)
        if pos == len(text):
            return fields
        pos += 1


def format_record(fields, delimiter=","):
    """Write fields as one delimited record."""
    _validate_delimiter(delimiter)
    try:
        iterator = iter(fields)
    except TypeError as exc:
        raise ValueError("Expected an iterable of fields") from exc

    encoded = []
    for field in iterator:
        if not isinstance(field, str):
            raise ValueError("Expected a string field")
        if (field.startswith(' ') or field.endswith(' ')
                or any(char in field for char in (delimiter, '"', '\r', '\n'))):
            field = '"' + field.replace('"', '""') + '"'
        encoded.append(field)
    if not encoded:
        raise ValueError("Expected at least one field")
    return delimiter.join(encoded)
